BEGIN;
CREATE TABLE ledger.accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, owner_type text NOT NULL, owner_id uuid, code text NOT NULL, kind ledger.account_kind NOT NULL, currency char(3) NOT NULL, status core.record_status NOT NULL DEFAULT 'ACTIVE', UNIQUE(tenant_id,code,currency));
CREATE TABLE ledger.transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, transaction_type text NOT NULL, status ledger.transaction_status NOT NULL DEFAULT 'DRAFT', idempotency_key text NOT NULL, correlation_id uuid NOT NULL, causation_id uuid, reversal_of uuid REFERENCES ledger.transactions(id), description text, created_at timestamptz NOT NULL DEFAULT now(), posted_at timestamptz, UNIQUE(tenant_id,idempotency_key), CHECK(reversal_of IS NULL OR reversal_of<>id));
CREATE TABLE ledger.entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES ledger.transactions(id) ON DELETE RESTRICT, account_id uuid NOT NULL REFERENCES ledger.accounts(id) ON DELETE RESTRICT, side ledger.entry_side NOT NULL, amount numeric(20,8) NOT NULL CHECK(amount>0), currency char(3) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger.wallets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES identity.users(id), currency char(3) NOT NULL, account_id uuid NOT NULL UNIQUE REFERENCES ledger.accounts(id), UNIQUE(tenant_id,user_id,currency));
COMMIT;
